      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
    });
    if (response.ok) { input.value = ''; await render(); }
  });
  await render();
}

* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fa; color: #182230; font: 16px/1.5 system-ui, sans-serif; }
.container { width: min(760px, calc(100% - 32px)); margin: 48px auto; padding: 32px; background: white; border: 1px solid #dce2ea; border-radius: 12px; }
h1 { margin-top: 0; font-size: 2rem; }
h2 { margin-top: 32px; font-size: 1.2rem; }
label { display: block; margin-bottom: 6px; font-weight: 600; }
.form-row { display: flex; gap: 10px; }
input { min-width: 0; flex: 1; padding: 10px 12px; border: 1px solid #9ba8b8; border-radius: 6px; font: inherit; }
button { padding: 10px 15px; border: 0; border-radius: 6px; color: white; background: #2459a6; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #174784; }
button:focus-visible, input:focus-visible { outline: 3px solid #78a9f5; outline-offset: 2px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #e2e7ee; }
#alert { color: #a21d27; margin: 8px 0 0; }
[hidden] { display: none !important; }
@media (max-width: 480px) { .container { padding: 22px; margin: 20px auto; } .form-row { align-items: stretch; flex-direction: column; } }

